"""Cross-check the compiled expression engine against a reference evaluator."""
import json, random, sys
sys.path.insert(0, '/workspace/project/src')
from eywa.ast import Bool, Char, Expr, Int, String, build_types, compile_expression

# ---- reference evaluator (independent of the package) ----
def ref_eval(node, env, types):
    head = node[0]
    if head == 'var':
        return env[node[1]]
    if head == 'const':
        return node[2]
    if head == 'field':
        return ref_eval(node[1], env, types)[node[2]]
    if head == 'index':
        return ref_eval(node[1], env, types)[node[2]]
    if head == 'all':
        binding, array_node, body = node[1], node[2], node[3]
        array = ref_eval(array_node, env, types)
        inner = dict(env)
        for element in array:
            inner[binding] = element
            if not ref_eval(body, inner, types):
                return False
        return True
    if head == 'match':
        return ref_match(node[2], ref_eval(node[1], env, types))
    if head == 'not':
        return not ref_eval(node[1], env, types)
    op = node[0]
    if op == 'and':
        return bool(ref_eval(node[1], env, types)) and bool(ref_eval(node[2], env, types))
    if op == 'or':
        return bool(ref_eval(node[1], env, types)) or bool(ref_eval(node[2], env, types))
    if op == 'implies':
        return (not ref_eval(node[1], env, types)) or bool(ref_eval(node[2], env, types))
    left = ref_eval(node[1], env, types)
    right = ref_eval(node[2], env, types)
    if op in ('eq', 'ne'):
        same = ref_equal(left, right)
        return same if op == 'eq' else not same
    if op == 'lt': return left < right
    if op == 'le': return left <= right
    if op == 'gt': return left > right
    if op == 'ge': return left >= right
    if op == 'add': return (left + right) % (1 << env['#bits'][node[1]])
    if op == 'sub': return (left - right) % (1 << env['#bits'][node[1]])
    raise AssertionError(op)

def ref_equal(a, b):
    if isinstance(a, bool) != isinstance(b, bool):
        return False
    if isinstance(a, dict):
        if not isinstance(b, dict) or len(a) != len(b): return False
        return all(k in b and ref_equal(v, b[k]) for k, v in a.items())
    if isinstance(a, list):
        if not isinstance(b, list) or len(a) != len(b): return False
        return all(ref_equal(x, y) for x, y in zip(a, b))
    if isinstance(b, (dict, list)): return False
    return a == b

def ref_match(pattern, text):
    # Backtracking reference matcher over Latin-1 code points.
    def parse(i):
        alts, seq = [], []
        while i < len(pattern) and pattern[i] != ')':
            if pattern[i] == '|':
                alts.append(seq); seq = []; i += 1
            else:
                atom, i = parse_atom(i)
                seq.append(atom)
        alts.append(seq)
        return alts, i
    def parse_atom(i):
        node = parse_primary(i)
        i = node[1]
        while i < len(pattern) and pattern[i] == '*':
            i += 1
            node = (('*', node[0]), i)
        return node
    def parse_primary(i):
        c = pattern[i]
        if c == '(':
            alts, j = parse(i + 1)
            return (('u', alts), j + 1)
        if c == '[':
            items = []
            j = i + 1
            while pattern[j] != ']':
                if pattern[j] == '\\':
                    low = pattern[j + 1]; j += 2
                else:
                    low = pattern[j]; j += 1
                if pattern[j] == '-' and pattern[j + 1] != ']':
                    if pattern[j + 1] == '\\':
                        high = pattern[j + 2]; j += 3
                    else:
                        high = pattern[j + 1]; j += 2
                    items.append((ord(low), ord(high)))
                else:
                    items.append((ord(low), ord(low)))
            return (('c', items), j + 1)
        if c == '\\':
            return (('l', pattern[i + 1]), i + 2)
        return (('l', c), i + 1)
    alts, _ = parse(0)
    def match_seq(seq, pos):
        if not seq:
            yield pos; return
        head, rest = seq[0], seq[1:]
        for after in match_atom(head, pos):
            yield from match_seq(rest, after)
    def match_atom(atom, pos):
        kind = atom[0]
        if kind == '*':
            inner = atom[1]
            positions = [pos]
            seen = {pos}
            index = 0
            while index < len(positions):
                here = positions[index]; index += 1
                yield here
                for after in match_atom(inner, here):
                    if after not in seen:
                        seen.add(after); positions.append(after)
            return
        if kind == 'l':
            if pos < len(text) and text[pos] == atom[1]:
                yield pos + 1
            return
        if kind == 'c':
            if pos < len(text) and any(low <= ord(text[pos]) <= high for low, high in atom[1]):
                yield pos + 1
            return
        for alt in atom[1]:
            yield from match_seq(alt, pos)
    return any(p == len(text) for p in match_seq(alts if False else ('u', alts), 0)[1] if False else []) or \
        any(True for _ in ()) or _match(alts, text)

def _match(alts, text):
    def match_seq(seq, pos):
        if not seq:
            yield pos; return
        for after in match_atom(seq[0], pos):
            yield from match_seq(seq[1:], after)
    def match_atom(atom, pos):
        kind = atom[0]
        if kind == '*':
            positions = [pos]; seen = {pos}; index = 0
            while index < len(positions):
                here = positions[index]; index += 1
                yield here
                for after in match_atom(atom[1], here):
                    if after not in seen:
                        seen.add(after); positions.append(after)
            return
        if kind == 'l':
            if pos < len(text) and text[pos] == atom[1]:
                yield pos + 1
            return
        if kind == 'c':
            if pos < len(text) and any(low <= ord(text[pos]) <= high for low, high in atom[1]):
                yield pos + 1
            return
        for alt in atom[1]:
            yield from match_seq(alt, pos)
    return any(p == len(text) for p in match_seq(('u', alts) if False else alts[0], 0)) or \
        any(p == len(text) for alt in alts for p in match_seq(alt, 0))

# ---- random campaign generation ----
def make_types(rng):
    decls = []
    bits = rng.choice([1, 3, 4, 8, 12, 16, 31, 32, 33, 63, 64])
    decls.append({'name': 'N', 'kind': 'int', 'bits': bits})
    decls.append({'name': 'B', 'kind': 'bool'})
    decls.append({'name': 'C', 'kind': 'char'})
    decls.append({'name': 'S', 'kind': 'string', 'maxsize': rng.randint(0, 5)})
    decls.append({'name': 'E', 'kind': 'enum', 'values': ['e0', 'e1', 'e2']})
    decls.append({'name': 'V', 'kind': 'array', 'element': 'N', 'size': rng.randint(0, 4)})
    decls.append({'name': 'T', 'kind': 'struct', 'fields': [['n', 'N'], ['b', 'B']]})
    decls.append({'name': 'W', 'kind': 'struct', 'fields': [['t', 'T'], ['s', 'S'], ['v', 'V']]})
    decls.append({'name': 'A', 'kind': 'alias', 'target': 'W'})
    decls.append({'name': 'VA', 'kind': 'array', 'element': 'T', 'size': rng.randint(0, 3)})
    types = build_types(decls)
    return decls, types, bits

def value_of(rng, kind, decls, name=''):
    if kind == 'int':
        bits = [d for d in decls if d['name'] == name]
        limit = (1 << (bits[0]['bits'] if bits else 16)) - 1
        return rng.randint(0, limit)
    if kind == 'bool': return rng.random() < 0.5
    if kind == 'char': return chr(rng.choice([0, 32, 65, 97, 255, 200]))
    if kind == 'string':
        size = [d for d in decls if d['name'] == name]
        return ''.join(rng.choice(['a', 'b', 'c', '\x00', '\xff']) for _ in range(size[0]['maxsize'] if size else 0))
    if kind == 'enum': return rng.choice(['e0', 'e1', 'e2'])
    if kind == 'array':
        size = [d for d in decls if d['name'] == name]
        return [rng.randint(0, 15) for _ in range(size[0]['size'] if size else 0)]
    if kind == 'struct': return {}
    raise AssertionError(kind)

class Gen:
    def __init__(self, rng, decls, types, scope):
        self.rng = rng; self.decls = decls; self.types = types; self.scope = scope
        self.bits = {}
        for d in decls:
            if d['kind'] == 'int': self.bits[d['name']] = d['bits']
        for name, t in scope.items():
            if isinstance(t, Int): self.bits[name] = t.bits

    def expr(self, depth, want=None):
        rng = self.rng
        names = list(self.scope)
        choices = ['var', 'const']
        if want is None:
            choices += ['and', 'or', 'implies', 'not', 'eq', 'ne', 'all', 'match']
        else:
            choices += ['eq', 'ne', 'not', 'all', 'match', 'and', 'or', 'implies']
        if depth <= 0:
            choices = ['var', 'const']
        kind = rng.choice(choices)
        if kind == 'var':
            if want == 'int':
                ints = [n for n in names if isinstance(self.scope[n], Int)]
                return ['var', rng.choice(ints or names)]
            return ['var', rng.choice(names)]
        if kind == 'const':
            if want == 'int':
                name = rng.choice(list(self.bits) or ['N'])
                bits = self.bits[name]
                return ['const', name, rng.randint(0, (1 << bits) - 1)]
            name = rng.choice(['N', 'B', 'C', 'S', 'E'])
            return ['const', name, value_of(rng, {'N': 'int', 'B': 'bool', 'C': 'char',
                                                  'S': 'string', 'E': 'enum'}[name],
                                            self.decls, name)]
        if kind == 'not':
            return ['not', self.expr(depth - 1, 'bool')]
        if kind in ('and', 'or', 'implies'):
            return [kind, self.expr(depth - 1, 'bool'), self.expr(depth - 1, 'bool')]
        if kind in ('eq', 'ne'):
            inner = self.expr(depth - 1)
            return [kind, inner, inner]
        if kind in ('lt', 'le', 'gt', 'ge', 'add', 'sub'):
            name = rng.choice(list(self.bits) or ['N'])
            return [kind, ['var', name] if rng.random() < 0.7 else ['const', name, rng.randint(0, (1 << self.bits[name]) - 1)],
                    ['var', name] if rng.random() < 0.7 else ['const', name, rng.randint(0, (1 << self.bits[name]) - 1)]]
        if kind == 'all':
            arrays = [n for n in names if isinstance(self.scope[n], type(build_types([])['N']))]
            name = rng.choice([n for n in names if n in self.bits] or ['N'])
            binding = 'z%d' % rng.randint(0, 3)
            inner_scope = dict(self.scope); inner_scope[binding] = self.types['N']
            sub = Gen(self.rng, self.decls, self.types, inner_scope)
            return ['all', binding, ['var', rng.choice([n for n in names if isinstance(self.scope[n], type(self.types['V']))] or ['V'])],
                    sub.expr(depth - 1, 'bool')]
        if kind == 'match':
            strings = [n for n in names if isinstance(self.scope[n], String)] or ['x']
            return ['match', ['var', rng.choice(strings)], self.pattern()]
        raise AssertionError(kind)

    def pattern(self):
        rng = self.rng
        pieces = []
        for _ in range(rng.randint(0, 3)):
            alt = []
            for _ in range(rng.randint(0, 3)):
                atom = rng.choice(['a', 'b', 'c', '[a-c]', '[^]', '(a|b)', 'ab', '[ab]', '\\.', 'x'])
                if rng.random() < 0.3:
                    atom = atom + '*'
                alt.append(atom)
            pieces.append(''.join(alt))
        return '|'.join(pieces)

rng = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 0)
fails = 0
for trial in range(400):
    decls, types, bits = make_types(rng)
    params = [('n', 'N'), ('b', 'B'), ('c', 'C'), ('s', 'S'), ('e', 'E'),
              ('v', 'V'), ('w', 'W'), ('a', 'A'), ('ta', 'VA')]
    scope = {}
    env = {}
    for name, type_name in params:
        decl = [d for d in decls if d['name'] == type_name][0]
        scope[name] = types[type_name]
        if decl['kind'] == 'struct':
            env[name] = {'n': rng.randint(0, 15), 'b': rng.random() < 0.5}
        elif decl['kind'] == 'alias':
            env[name] = {'n': rng.randint(0, 15), 'b': rng.random() < 0.5,
                         's': ''.join(rng.choice('ab\x00') for _ in range(decls[3]['maxsize'])),
                         'v': [rng.randint(0, 15) for _ in range(decls[5]['size'])]}
        else:
            env[name] = value_of(rng, decl['kind'], decls, name)
    env['#bits'] = {}
    for name, t in scope.items():
        if isinstance(t, Int): env['#bits'][name] = t.bits
    gen = Gen(rng, decls, types, scope)
    tree = gen.expr(3)
    # reference evaluation
    try:
        want = ref_eval(tree, env, types)
    except Exception as exc:
        continue
    try:
        compiled = compile_expression(tree, dict(scope), types)
        got = Expr.eval(compiled, dict(env))
    except Exception as exc:
        print('COMPILE/EVAL FAIL', trial, tree, exc); fails += 1
        if fails > 3: break
        continue
    if got != want:
        print('MISMATCH', trial, json.dumps(tree))
        print('  env', json.dumps(env, sort_keys=True, default=str))
        print('  got', got, 'want', want); fails += 1
        if fails > 3: break
print('expression fuzz done, failures:', fails)
